const Imap = require('imap');
const { simpleParser } = require('mailparser');

const cfg = $input.first().json;
const imap = new Imap({
  user: cfg.imapUser,
  password: cfg.imapPassword,
  host: cfg.imapHost,
  port: 993,
  tls: true,
  tlsOptions: { rejectUnauthorized: false }
});

const emails = await new Promise((resolve, reject) => {
  const results = [];

  imap.once('ready', () => {
    imap.openBox('INBOX', false, (err) => {
      if (err) return reject(err);

      imap.search(['ALL'], (err, uids) => {
        if (err) return reject(err);
        if (!uids.length) return resolve([]);

        const slice = uids.slice(0, 200);

        const f = imap.fetch(slice, {
          bodies: 'HEADER',
          struct: true
        });

        f.on('message', (msg, seqno) => {
          msg.on('body', (stream) => {
            simpleParser(stream, (err, parsed) => {
              if (!err) {
                results.push({
                  uid: slice[seqno - 1],
                  from: parsed.from?.text ?? 'unknown',
                  subject: parsed.subject ?? '(no subject)',
                  date: parsed.date ?? null
                });
              }
            });
          });
        });

        f.once('end', () => {
          // wait for all simpleParser callbacks to finish
          setTimeout(() => {
            imap.end();
            resolve(results);
          }, 3000);
        });

        f.once('error', reject);
      });
    });
  });

  imap.once('error', reject);
  imap.connect();
});

return emails.map(e => ({ json: e }));

return $input.all().map(item => {
  const from = item.json.from ?? '';
  const match = from.match(/@([\w.-]+)/);
  const domain = match ? match[1].toLowerCase() : 'unknown';

  return {
    json: {
      ...item.json,
      domain
    }
  };
});

const items = $input.all();

const groups = {};
for (const item of items) {
  const domain = item.json.domain ?? 'unknown';
  const uid = item.json.uid; // must be 'uid' not 'uids'

  if (uid === undefined || uid === null) continue;

  if (!groups[domain]) groups[domain] = [];
  groups[domain].push(uid);
}

// Log to verify
console.log('Groups found:', Object.keys(groups));
console.log('Sample:', JSON.stringify(Object.entries(groups)[0]));

return Object.entries(groups).map(([domain, uids]) => ({
  json: { domain, uids }
}));

const Imap = require('imap');

const cfg = $('Config').first().json;
