const uids = $input.first().json.uids;
const folderName = `Organised/${domain}`;

const imap = new Imap({
  user: cfg.imapUser,
  password: cfg.imapPassword,
  host: cfg.imapHost,
  port: 993,
  tls: true,
  tlsOptions: { rejectUnauthorized: false }
});

await new Promise((resolve) => {
  imap.once('ready', () => {
    imap.addBox(folderName, () => {
      imap.end();
      resolve();
    });
