  imap.connect();
});

return [{ json: { domain, folderName, uids } }];

const Imap = require('imap');

const domain = $input.first().json.domain;
const folderName = $input.first().json.folderName;
const uids = $input.first().json.uids
  .flat()
  .map(u => parseInt(u))
  .filter(u => !isNaN(u));

if (!uids.length) {
  return [{ json: { done: true, domain, moved: 0 } }];
}

const cfg = $('Config').first().json;
const imap = new Imap({
  user: cfg.imapUser,
  password: cfg.imapPassword,
  host: cfg.imapHost,
  port: 993,
  tls: true,
  tlsOptions: { rejectUnauthorized: false }
});

await new Promise((resolve, reject) => {
  imap.once('ready', () => {
    imap.openBox('INBOX', false, (err) => {
      if (err) return reject(err);

      // Try MOVE first, fall back to COPY + DELETE
      imap.move(uids, folderName, (moveErr) => {
        if (!moveErr) {
          imap.end();
          return resolve();
        }

        // Fallback: COPY then DELETE
        imap.copy(uids, folderName, (copyErr) => {
          if (copyErr) return reject(copyErr);

          imap.addFlags(uids, '\\Deleted', (flagErr) => {
            if (flagErr) return reject(flagErr);

            imap.expunge((expErr) => {
              if (expErr) return reject(expErr);
              imap.end();
              resolve();
            });
          });
        });
      });
    });
  });

  imap.once('error', reject);
  imap.connect();
});

return [{ json: { done: true, domain, moved: uids.length } }];
